const statuses=['To Do','In Progress','Blocked','Completed','Delayed'];
const categories=['Research','Requirements','Architecture','Hardware','AI Models','Backend','Mobile App','AWS','Meeting MOM','Reports','Final Documentation'];
const nav=[['dashboard','Overview',LayoutDashboard],['tasks','My Tasks',ListTodo],['weekly','Weekly Plan',CalendarDays],['monthly','Monthly Plan',CalendarRange],['timeline','Timeline & Roadmap',Route],['journey','Project Journey',MapIcon],['analytics','Progress & Analytics',ChartNoAxesCombined],['team','Team',Users],['meetings','Meetings / MOM',NotebookPen],['documents','Documents',FolderOpen],['activity','Activity & History',Activity],['search','Search',Search],['settings','Settings',Settings]] as const;
